-- Canonical compatibility for configured WORKER_ACTUAL and legacy DIRECT_ACTUAL material methods.
create or replace function public.rr_material_direct_pending_v659(p_assignment_id uuid,p_data_mode text default 'TEST') returns jsonb language plpgsql stable security definer set search_path to 'public' as $function$
declare a record;begin select * into a from public.rr_upm_work_assignments_v8 where id=p_assignment_id;if not found then return jsonb_build_object('rows','[]'::jsonb);end if;return jsonb_build_object('version','V659_WORKER_DIRECT_ALIAS','rows',coalesce((select jsonb_agg(jsonb_build_object('mapping_id',x.id,'material_id',m.id,'material_name',m.material_name,'unit',m.consumption_unit,'weighted_rate',s.weighted_avg_rate_per_consumption_unit,'execution_decision',x.execution_decision,'method',x.consumption_method)) from public.rr_material_consumption_mapping_v655 x join public.rr_material_master_v805 m on m.id=x.material_id left join public.rr_material_stock_v805 s on s.material_id=m.id and upper(s.data_mode)=upper(p_data_mode) where x.is_active and upper(x.consumption_method) in('DIRECT_ACTUAL','WORKER_ACTUAL') and x.effective_from<=current_date and (x.execution_decision or public.rr_upm_core_department_v9077(x.consume_department_code)=public.rr_upm_core_department_v9077(a.department_code)) and not exists(select 1 from public.rr_material_execution_consumption_v655 e where e.canonical_lot_id=a.canonical_lot_id and e.material_id=x.material_id and upper(e.data_mode)=upper(p_data_mode))),'[]'::jsonb));end $function$;
-- Confirm uses same weighted stock authority and writes once into canonical material consumption ledger.
create or replace function public.rr_material_direct_confirm_v659(p_assignment_id uuid,p_mapping_id uuid,p_consumed_qty numeric,p_data_mode text default 'TEST') returns jsonb language plpgsql security definer set search_path to 'public' as $function$
declare a record;x record;m record;s record;v_role text;v_good numeric;v_total numeric;v_id uuid;begin v_role:=upper(coalesce(public.rr_costing_user_scope_v760(null)->>'effective_role',''));if v_role not in('OWNER','SUPER_ADMIN','ADMIN','MANAGER','LINE_MANAGER','LINE_MAN','CUTTING_MASTER','DEPARTMENT_HEAD') then raise exception 'Lineman / Manager confirmation required.';end if;if coalesce(p_consumed_qty,-1)<0 then raise exception 'Consumed Qty required.';end if;select * into a from public.rr_upm_work_assignments_v8 where id=p_assignment_id for update;if not found then raise exception 'Assignment not found';end if;select * into x from public.rr_material_consumption_mapping_v655 where id=p_mapping_id and is_active and upper(consumption_method) in('DIRECT_ACTUAL','WORKER_ACTUAL');if not found then raise exception 'Worker/Direct Actual mapping not found';end if;if not x.execution_decision and public.rr_upm_core_department_v9077(x.consume_department_code)<>public.rr_upm_core_department_v9077(a.department_code) then raise exception 'Material is not mapped to this department.';end if;select * into m from public.rr_material_master_v805 where id=x.material_id;select * into s from public.rr_material_stock_v805 where material_id=m.id and upper(data_mode)=upper(p_data_mode);v_good:=greatest(coalesce((select confirmed_qty from public.rr_upm_assignment_receipts_v9112 where assignment_id=a.id order by confirmed_at desc nulls last limit 1),0),coalesce(a.inbound_qty,0),coalesce(a.assigned_qty,0));v_total:=case when s.weighted_avg_rate_per_consumption_unit is null then null else p_consumed_qty*s.weighted_avg_rate_per_consumption_unit end;if v_total is null then raise exception 'Weighted purchase rate missing for material %.',m.material_name;end if;insert into public.rr_material_execution_consumption_v655(data_mode,canonical_lot_id,lot_no,material_id,mapping_id,assignment_id,department_code,worker_id,confirmed_by,consumed_qty,unit,weighted_rate_snapshot,total_cost,cost_per_good_piece,source_record_id) values(upper(p_data_mode),a.canonical_lot_id,a.lot_no,m.id,x.id,a.id,public.rr_upm_core_department_v9077(a.department_code),public.rr_canonical_worker_id_v264(a.worker_id),auth.uid(),p_consumed_qty,m.consumption_unit,s.weighted_avg_rate_per_consumption_unit,v_total,v_total/nullif(v_good,0),'DIRECT:'||a.canonical_lot_id||':'||m.id::text) on conflict(data_mode,canonical_lot_id,material_id) do nothing returning id into v_id;if v_id is null then return jsonb_build_object('ok',true,'duplicate_blocked',true,'material',m.material_name);end if;insert into public.rr_material_consumption_v805(material_id,source_module,source_record_id,lot_no,applicable_qty,consumption_qty,consumption_unit,base_qty_consumed,weighted_rate_per_base_unit,weighted_rate_per_consumption_unit,cost_per_good_piece,total_consumption_cost,consumption_basis,data_mode) values(m.id,'DIRECT_ACTUAL','DIRECT:'||a.canonical_lot_id||':'||m.id::text,a.lot_no,v_good,p_consumed_qty,m.consumption_unit,p_consumed_qty*coalesce(m.consumption_to_base,1),s.weighted_avg_rate_per_base_unit,s.weighted_avg_rate_per_consumption_unit,v_total/nullif(v_good,0),v_total,'CONFIRMED_BY_'||v_role,upper(p_data_mode)) on conflict(material_id,source_module,source_record_id,data_mode) do nothing;return jsonb_build_object('ok',true,'version','V659_WORKER_DIRECT_ALIAS','material',m.material_name,'consumed_qty',p_consumed_qty,'unit',m.consumption_unit,'weighted_rate',s.weighted_avg_rate_per_consumption_unit,'total_cost',v_total,'duplicate_blocked',false);end $function$;